package com.singularity.todo.core.sync

import java.io.File
import kotlinx.serialization.json.JsonObject
import org.junit.jupiter.api.Tag
import org.junit.jupiter.api.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * The committed field lists must be the ones the models declare.
 *
 * The file `config/docs/sync-field-allowlist.json` is generated by
 * `:shared:exportSyncFieldAllowlist` from the compiled models, and the seed
 * generator and the gate read that file instead of parsing the Kotlin source.
 * This test is the half that says the committed file is current, so a
 * hand-edit of it is reported rather than believed.
 *
 * The three facts line up like this:
 *
 * - the models declare the fields (the descriptors),
 * - the export is those fields, written down,
 * - the seed and the gate read the export.
 *
 * A parser that misreads a model used to break the last link silently: the
 * regular expression that read the Kotlin source stopped at the first closing
 * parenthesis — inside a comment — and the gate that checked the file compared
 * it with the same truncated list.
 */
@Tag("fast")
class SyncFieldAllowlistExportTest {

    @Test
    fun `the committed field lists are the ones the models declare`() {
        val committed = File(repoRoot(), "config/docs/sync-field-allowlist.json")
        assertTrue(
            committed.isFile,
            "the field lists have not been exported: ${committed.absolutePath} is missing — " +
                "run ./gradlew :shared:exportSyncFieldAllowlist",
        )

        // The same comparison the fast Gradle check makes: the parsed lists,
        // not the text. The question is whether the file says the same thing
        // as the models — not whether it says it with the same whitespace —
        // and the two checks ask it through one function, so they cannot
        // drift into asking different questions.
        assertTrue(
            SyncFieldAllowlistExport.matches(committed),
            "the committed field lists differ from the ones the models declare — " +
                "run ./gradlew :shared:exportSyncFieldAllowlist and commit the result",
        )
    }

    @Test
    fun `the export carries every document type the client syncs`() {
        val exported = SyncFieldAllowlistExport.export()
        val docTypes = exported["docTypes"] as? JsonObject ?: error("the export has no docTypes")

        assertEquals(
            SyncContract.SYNCABLE_DOC_TYPES.map { it.key }.sorted(),
            docTypes.keys.sorted(),
            "the export must carry every document type the client syncs — a type that is " +
                "not exported is a type the gate cannot see",
        )
    }

    @Test
    fun `the export spells the entity types the way the server does`() {
        val exported = SyncFieldAllowlistExport.export()
        val docTypes = exported["docTypes"] as? JsonObject ?: error("the export has no docTypes")

        for (docType in SyncContract.SYNCABLE_DOC_TYPES) {
            assertTrue(
                docType.key in docTypes,
                "the export spells '${docType.key}' as the DocType key — the server looks " +
                    "the type up by that name, and a seed that spells it differently holds " +
                    "rows the server never reads",
            )
        }
    }

    /**
     * The repository root, found by walking up from the working directory.
     *
     * The test runs with the module directory as its working directory, and the depth
     * is not something to hard-code: a path that is right today and wrong after a
     * directory is renamed is a failure nobody can explain.
     */
    private fun repoRoot(): File = generateSequence(File(System.getProperty("user.dir")).absoluteFile) {
        it.parentFile
    }
        .firstOrNull { File(it, "config/docs/adr-corpus.json").isFile }
        ?: error("could not find the repository root from ${System.getProperty("user.dir")}")
}
